let activeRelation=null,relationOwner=null,relationOpacity=null;
let organContext=null,organMaterials=[];
function clearRelation(){stopPhysiology();$('#relation-targets')?.remove();organMaterials.forEach(r=>{r.material.side=r.side;r.material.clippingPlanes=r.clippingPlanes;r.material.opacity=r.opacity;r.material.transparent=r.transparent;r.material.depthWrite=r.depthWrite;r.material.needsUpdate=true});organMaterials=[];organContext=null;$('#surface-controls')?.remove();activeRelation=null;relationOwner=null;if(relationOpacity!==null){$('#opacity').value=relationOpacity;relationOpacity=null;opacity(false)}document.querySelectorAll('[data-relation]').forEach(b=>{b.setAttribute('aria-pressed','false');b.removeAttribute('aria-busy')});const status=$('#relation-status');if(status)status.hidden=true;}
function relationStatus(text){$('#relation-targets')?.remove();const s=$('#relation-status');if(s){s.textContent=text;s.hidden=false}}
function revealRelation(){if(innerWidth<=760){closePanel();const reconstructed=selected?.id==='gluteus'&&activeRelation==='nerve';notify(reconstructed?'Nervio glúteo inferior · reconstrucción educativa':'Relación visible. Gira o acerca el modelo para estudiarla.')}else $('#notice').hidden=true}
async function relationView(mode){
 if(selected?.data.studyOrgan)return organRelationView(mode);
 if(!selected?.data.action)return;
 if(activeRelation===mode&&relationOwner===selected){clearRelation();attachmentView();revealRelation();return}
 clearRelation();const owner=selected,epoch=++filterVersion;activeRelation=mode;relationOwner=owner;
 const button=$('[data-relation="'+mode+'"]');button?.setAttribute('aria-pressed','true');button?.setAttribute('aria-busy','true');
 const kind=mode==='nerve'?'nervous':mode==='irrigation'?'arterial':'skeletal';
 relationStatus(kind==='skeletal'?'Mostrando los huesos…':'Cargando las estructuras relacionadas…');
 try{
  await ensureSystem(kind);if(epoch!==filterVersion||selected!==owner)return;
  if(kind==='skeletal'){
   attachmentView(mode);relationStatus('Huesos del '+(mode==='origin'?'origen':'lugar de inserción')+': '+[...new Set(visibleParts().filter(p=>p.system==='skeletal').map(p=>displayName(p.name)))].join(', ')+'. La ficha indica el punto de fijación.');
  }else{
   if(owner.id==='gluteus'&&mode==='nerve')addGlutealNerves(THREE,parts,matFor('nervous','#d3c3a3',false));
   const pattern=new RegExp((mode==='nerve'?owner.data.nerveMatch:owner.data.arteryMatch)||'^$');
   const targets=parts.filter(p=>p.system===kind&&(!p.side||p.side===owner.side)&&pattern.test(p.name.toLowerCase().replace(/[.\s]+/g,'_')));
   if(!targets.length){clearRelation();attachmentView();relationStatus('La ficha describe esta relación, pero '+(mode==='nerve'?'este nervio todavía no está modelado':'estas arterias todavía no están modeladas')+' en el atlas.');return}
   studyKeys.clear();[...selectedParts(),...targets].forEach(p=>{studyKeys.add(p.key);hidden.delete(p.key)});
   studyMode=true;isolation=false;region='all';halfMuscles=false;heartCut=false;$('#half-muscles').checked=false;
   enabled.clear();enabled.add('muscular');enabled.add(kind);$('#isolate').textContent='Aislar';$('#isolate').setAttribute('aria-pressed','false');
   relationOpacity=$('#opacity').value;$('#opacity').value=Math.max(Number(relationOpacity),owner.id==='gluteus'?85:65);opacity(false);
   updateRegionUI();rebuild();focusParts([...selectedParts(),...targets]);
   relationStatus('Visible: '+[...new Set(targets.map(p=>displayName(p.name)))].join(', ')+'.'+(targets.some(p=>p.reconstructed)?' Reconstrucción educativa del trayecto infrapiriforme y de la distribución sobre la cara profunda. Las raíces y variantes individuales no se representan.':mode==='irrigation'?' Vasos originales del atlas; las ramas intramusculares pequeñas no están representadas.':''));
   showRelationTargets(targets);
   openPanel('learn');
  }
  revealRelation();
 }catch(e){if(epoch===filterVersion&&selected===owner){clearRelation();relationStatus('No se pudo cargar esta vista. Toca el apartado para reintentar.')}console.error(e)}
 finally{button?.removeAttribute('aria-busy')}
}
function showRelationTargets(targets){
 const status=$('#relation-status');if(!status)return;
 const row=document.createElement('div');row.id='relation-targets';row.className='relation-targets';
 for(const key of new Set(targets.map(p=>p.key))){const items=targets.filter(p=>p.key===key),b=document.createElement('button');b.type='button';b.textContent=displayName(items[0].name);b.onclick=()=>{focusParts(items);document.querySelectorAll('#relation-targets button').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));if(innerWidth<=760)closePanel()};row.append(b)}
 const all=document.createElement('button');all.type='button';all.textContent='Ver relación completa';all.onclick=()=>focusParts([...selectedParts(),...targets]);row.append(all);status.after(row);
}
