// Study view: source coordinates remain fixed; only the selected shell is cut.
let surfaceMode='window',surfaceCut=50;
const studyPlane=new THREE.Plane(new THREE.Vector3(0,0,-1),0);
function applyStudySurface(){
 if(!organMaterials.length||!selected)return;
 const box=new THREE.Box3();selectedParts().forEach(p=>box.union(p.box));
 studyPlane.constant=box.max.z-(box.max.z-box.min.z)*surfaceCut/100;
 for(const {material:m} of organMaterials){
  const planes=(m.clippingPlanes||[]).filter(p=>p!==studyPlane);
  if(surfaceMode==='window')planes.push(studyPlane);
  m.clippingPlanes=planes;m.side=surfaceMode==='ghost'?THREE.FrontSide:THREE.DoubleSide;
  m.transparent=surfaceMode==='ghost';m.opacity=surfaceMode==='ghost'?.32:1;
  m.depthWrite=true;m.forceSinglePass=true;m.needsUpdate=true;
 }
}
function showSurfaceControls(){
 $('#surface-controls')?.remove();if(!organMaterials.length)return;
 const box=document.createElement('section');box.id='surface-controls';box.className='study-surface';
 box.innerHTML='<h3>Cómo ver el órgano</h3><div class="surface-modes">'+[['solid','Superficie'],['window','Ventana'],['ghost','Transparente']].map(([id,title])=>'<button data-surface="'+id+'" aria-pressed="'+(surfaceMode===id)+'">'+title+'</button>').join('')+'</div><label for="surface-cut">Apertura de la ventana <output>'+surfaceCut+'%</output></label><input id="surface-cut" type="range" min="0" max="95" value="'+surfaceCut+'"><p>La ventana oculta una parte de la superficie para explorar las estructuras profundas. No representa un corte histológico.</p>';
 box.querySelectorAll('[data-surface]').forEach(b=>b.onclick=()=>{surfaceMode=b.dataset.surface;applyStudySurface();rebuild();showSurfaceControls()});
 box.querySelector('input').oninput=e=>{surfaceCut=Number(e.target.value);box.querySelector('output').textContent=surfaceCut+'%';applyStudySurface();render()};
 box.querySelector('input').disabled=surfaceMode!=='window';$('#relation-status')?.before(box);
}

let lessonOwner=null,lessonIndex=0,lessonTimer=null,lessonAutoplay=false,lessonVersion=0;
function stopLesson(){lessonVersion++;filterVersion++;clearTimeout(lessonTimer);lessonTimer=null;lessonOwner=null;lessonAutoplay=false;$('#lesson-card')?.remove();stopPhysiology()}
function showStudyTools(){
 if(!selected)return;
 const tools=document.createElement('div');tools.className='study-tools';
 const guide=document.createElement('button');guide.textContent='Estudiar paso a paso';guide.onclick=()=>{lessonOwner=selected;lessonIndex=0;lessonAutoplay=false;studyStep(0)};tools.append(guide);
 const d=physiology[selected.id];if(d){const b=document.createElement('button');b.id='physiology-play';b.textContent=physiologyPlaying?'Pausar '+d.label.toLowerCase():'Animar '+d.label.toLowerCase();b.onclick=togglePhysiology;tools.append(b);}
 $('#info').prepend(tools);
}
async function studyStep(index){
 clearTimeout(lessonTimer);const stepVersion=++lessonVersion,owner=lessonOwner;if(!owner||owner!==selected)return;
 const steps=lessonSteps(owner.data);lessonIndex=Math.max(0,Math.min(index,steps.length-1));const step=steps[lessonIndex];
 if(['origin','insertion','irrigation','nerve','lymph'].includes(step.mode)){if(activeRelation!==step.mode||relationOwner!==owner)await relationView(step.mode);}
 else {
  filterVersion++;clearRelation();studyKeys.clear();let items=selectedParts();enabled.clear();enabled.add(owner.data.system);
  if(step.mode==='location'){
   const box=new THREE.Box3();items.forEach(p=>box.union(p.box));box.expandByScalar(.25);
   const nearby=parts.filter(p=>p.system==='skeletal'&&(!owner.side||!p.side||p.side===owner.side)&&box.containsPoint(p.box.getCenter(new THREE.Vector3())));
   items=[...items,...nearby];enabled.add('skeletal');
  }
  items.forEach(p=>{studyKeys.add(p.key);hidden.delete(p.key)});studyMode=true;isolation=false;region='all';halfMuscles=false;heartCut=false;$('#half-muscles').checked=false;updateRegionUI();rebuild();focusParts(items);
 }
 if(lessonOwner!==owner||selected!==owner||stepVersion!==lessonVersion)return;
 $('#lesson-card')?.remove();const card=document.createElement('section');card.id='lesson-card';card.className='lesson-card';
 card.innerHTML='<div class="lesson-progress">'+(lessonIndex+1)+' / '+steps.length+' · '+html(owner.data.name)+'</div><h3>'+html(step.title)+'</h3><p>'+html(step.body)+'</p><div class="lesson-navigation"><button id="lesson-prev" '+(!lessonIndex?'disabled':'')+'>← Anterior</button><button id="lesson-next" '+(lessonIndex===steps.length-1?'disabled':'')+'>Siguiente →</button></div><div class="lesson-navigation"><button id="lesson-auto" aria-pressed="'+lessonAutoplay+'">'+(lessonAutoplay?'Pausar recorrido':'Reproducir recorrido')+'</button><button id="lesson-end">Cerrar recorrido</button></div>';
 if(step.mode==='components'){
  const list=document.createElement('div');list.className='component-list';
  const pieces=selectedParts();for(const key of [...new Set(pieces.map(p=>p.key))].slice(0,24)){
   const group=pieces.filter(p=>p.key===key),b=document.createElement('button');b.textContent=displayName(group[0].name);b.onclick=()=>{if(owner.data.system==='sensory'){studyKeys.clear();group.forEach(p=>studyKeys.add(p.key));rebuild()}focusParts(group);list.querySelectorAll('button').forEach(n=>n.setAttribute('aria-pressed',String(n===b)))};list.append(b);
  }card.append(list);
 }
 $('#info').prepend(card);card.querySelector('#lesson-prev').onclick=()=>studyStep(lessonIndex-1);card.querySelector('#lesson-next').onclick=()=>studyStep(lessonIndex+1);
 card.querySelector('#lesson-end').onclick=()=>{stopLesson();showInfo()};
 card.querySelector('#lesson-auto').onclick=()=>{lessonAutoplay=!lessonAutoplay;studyStep(lessonIndex)};
 openPanel('learn');$('.drawer-content').scrollTop=0;
 if(lessonAutoplay&&lessonIndex<steps.length-1)lessonTimer=setTimeout(()=>studyStep(lessonIndex+1),8000);
 else if(lessonIndex===steps.length-1){lessonAutoplay=false;card.querySelector('#lesson-auto').textContent='Reproducir recorrido';card.querySelector('#lesson-auto').setAttribute('aria-pressed','false')}
}

let physiologyPlaying=false,physiologyTime=0,motionMeshes=[];
function motionGroup(p){if(!selected?.keys.has(p.key))return 'fixed';if(selected.id==='heart'){if(/^(left|right) atrium$/i.test(p.name))return 'atrial';if(/^(left|right) ventricle$|papillary|trabecula|interventricular/i.test(p.name))return 'ventricular';return 'fixed'}return ['ureters','oesophagus'].includes(selected.id)?p.key:'moving'}
function stopPhysiology(){
 physiologyPlaying=false;for(const entry of motionMeshes){entry.mesh.position.set(0,0,0);entry.mesh.scale.set(1,1,1);if(entry.original){entry.mesh.geometry.attributes.position.array.set(entry.original);entry.mesh.geometry.attributes.position.needsUpdate=true;entry.mesh.geometry.attributes.normal.array.set(entry.normal);entry.mesh.geometry.attributes.normal.needsUpdate=true;}}
 motionMeshes=[];$('#motion-caption')?.remove();const b=$('#physiology-play');if(b&&selected)b.textContent='Animar '+(physiology[selected.id]?.label||'función').toLowerCase();
}
function togglePhysiology(){
 if(physiologyPlaying){stopPhysiology();render();return}if(!selected||!physiology[selected.id])return;
 stopLesson();clearRelation();studyMode=true;isolation=false;region='all';enabled.clear();enabled.add(selected.data.system);studyKeys.clear();selectedParts().forEach(p=>{studyKeys.add(p.key);hidden.delete(p.key)});physiologyTime=0;physiologyPlaying=true;updateRegionUI();rebuild();focusParts(selectedParts());
 motionMeshes=batches.filter(m=>m.userData.motionGroup!=='fixed').map(mesh=>{
  const center=mesh.geometry.boundingBox||new THREE.Box3().setFromBufferAttribute(mesh.geometry.attributes.position);
  const original=['oesophagus','ureters'].includes(selected.id)?mesh.geometry.attributes.position.array.slice():null;
  const axis=original?Array.from({length:32},()=>({x:0,z:0,n:0})):null;
  if(axis){const height=Math.max(center.max.y-center.min.y,.0001);for(let i=0;i<original.length;i+=3){const bin=Math.min(31,Math.max(0,Math.floor((original[i+1]-center.min.y)/height*31)));axis[bin].x+=original[i];axis[bin].z+=original[i+2];axis[bin].n++;}for(const point of axis)if(point.n){point.x/=point.n;point.z/=point.n;}for(let i=0;i<32;i++)if(!axis[i].n){let j=1;while(j<32&&!axis[Math.max(0,i-j)].n&&!axis[Math.min(31,i+j)].n)j++;const found=axis[Math.max(0,i-j)].n?axis[Math.max(0,i-j)]:axis[Math.min(31,i+j)];axis[i]={...found};}}
  return {mesh,normal:mesh.geometry.attributes.normal.array.slice(),motionGroup:mesh.userData.motionGroup,center:center.getCenter(new THREE.Vector3()),box:center.clone(),original,axis};
 });
  const caption=document.createElement('div');caption.id='motion-caption';caption.className='motion-caption';caption.innerHTML='<strong></strong><span>Movimiento esquemático · Saladin, capítulo '+physiology[selected.id].chapter+'</span><button>⏸ Pausar</button>';caption.querySelector('button').onclick=()=>{stopPhysiology();render()};$('#stage').parentElement.append(caption);$('#physiology-play').textContent='Pausar '+physiology[selected.id].label.toLowerCase();$('#notice').hidden=true;
 render();
}
function updatePhysiology(dt){
 if(!selected||!physiologyPlaying)return;physiologyTime+=dt;const state=motionState(selected.id,physiologyTime);if(!state)return;
 for(const entry of motionMeshes){
  const {mesh,center:c}=entry;const local=motionState(selected.id,physiologyTime,entry.motionGroup);mesh.scale.set(...local.scale);mesh.position.set(c.x*(1-local.scale[0]),c.y*(1-local.scale[1]),c.z*(1-local.scale[2]));
  if(entry.original){const pos=mesh.geometry.attributes.position.array,base=entry.original,height=entry.box.max.y-entry.box.min.y;
   for(let i=0;i<pos.length;i+=3){const level=(entry.box.max.y-base[i+1])/Math.max(height,.0001),dist=Math.abs(level-state.wave),factor=1-.075*Math.exp(-dist*dist/.0025),bin=Math.min(31,Math.max(0,(1-level)*31)),lo=Math.floor(bin),hi=Math.min(31,lo+1),t=bin-lo,ax=entry.axis[lo].x*(1-t)+entry.axis[hi].x*t,az=entry.axis[lo].z*(1-t)+entry.axis[hi].z*t;pos[i]=ax+(base[i]-ax)*factor;pos[i+2]=az+(base[i+2]-az)*factor;}
   mesh.geometry.attributes.position.needsUpdate=true;
  }
 }
 const label=$('#motion-caption strong');if(label)label.textContent=physiology[selected.id].phases[state.phase];
}
window.musclePreview.studyStep=index=>{if(!lessonOwner)lessonOwner=selected;return studyStep(index)};
window.musclePreview.togglePhysiology=togglePhysiology;
window.musclePreview.stopPhysiology=stopPhysiology;
window.musclePreview.studySurface=mode=>{surfaceMode=mode;applyStudySurface();rebuild();showSurfaceControls()};

function restoreOrganContext(context){enabled.clear();context.enabled.forEach(id=>enabled.add(id));studyMode=context.studyMode;studyKeys.clear();context.keys.forEach(k=>studyKeys.add(k));isolation=context.isolation;region=context.region;halfMuscles=context.half;$('#half-muscles').checked=halfMuscles;$('#isolate').textContent=isolation?'Ver conjunto':'Aislar';$('#isolate').setAttribute('aria-pressed',String(isolation));updateRegionUI();rebuild();focusParts(visibleParts());}
async function organRelationView(mode){
 if(!['irrigation','nerve','lymph'].includes(mode)||!selected?.data.studyOrgan)return;
 const owner=selected;
 if(activeRelation===mode&&relationOwner===owner){const context=organContext;filterVersion++;clearRelation();if(context)restoreOrganContext(context);revealRelation();return}
 const context=organContext||{enabled:new Set(enabled),studyMode,keys:new Set(studyKeys),isolation,region,half:halfMuscles};
 clearRelation();organContext=context;relationOwner=owner;activeRelation=mode;const epoch=++filterVersion;
 const button=$('[data-relation="'+mode+'"]');button?.setAttribute('aria-pressed','true');button?.setAttribute('aria-busy','true');
 const kinds=mode==='irrigation'?(owner.data.irrigationSystems||['arterial']):mode==='nerve'?['nervous']:['lymphatic'];
 relationStatus('Cargando las estructuras relacionadas…');
 try{
  await Promise.all(kinds.map(ensureSystem));if(epoch!==filterVersion||selected!==owner)return;
  const pattern=new RegExp(owner.data[mode==='irrigation'?'arteryMatch':mode==='nerve'?'nerveMatch':'lymphMatch']);
  const targets=parts.filter(p=>kinds.includes(p.system)&&(!owner.side||!p.side||p.side===owner.side)&&pattern.test(p.name.toLowerCase().replace(/[.\s]+/g,'_')));
  studyKeys.clear();[...selectedParts(),...targets].forEach(p=>{studyKeys.add(p.key);hidden.delete(p.key)});
  enabled.clear();enabled.add(owner.data.system);targets.forEach(p=>enabled.add(p.system));studyMode=true;isolation=false;region='all';halfMuscles=false;heartCut=false;$('#half-muscles').checked=false;$('#isolate').textContent='Aislar';$('#isolate').setAttribute('aria-pressed','false');
  const materials=new Set(selectedParts().map(p=>p.material));organMaterials=[...materials].map(material=>({material,opacity:material.opacity,transparent:material.transparent,depthWrite:material.depthWrite,side:material.side,clippingPlanes:material.clippingPlanes}));
  if(targets.length){surfaceMode='ghost';surfaceCut=50;applyStudySurface();}
  updateRegionUI();rebuild();
  const anchor=new THREE.Box3();selectedParts().forEach(p=>anchor.union(p.box));anchor.expandByScalar(.2);
  const nearby=targets.filter(p=>anchor.intersectsBox(p.box));const focus=mode==='lymph'||!nearby.length?[...selectedParts(),...targets]:[...selectedParts(),...nearby.map(p=>({box:p.box.clone().intersect(anchor)}))];focusParts(focus);
  const names=[...new Set(targets.map(p=>displayName(p.name)))];
  relationStatus(names.length?'Visible: '+names.join(', ')+'. '+(mode==='lymph'?'Se muestran ganglios de drenaje; los vasos linfáticos finos y el trayecto completo no están modelados.':mode==='nerve'?'Se muestra el trayecto disponible, no una conexión terminal al órgano; los plexos autónomos y las ramas terminales no están representados en detalle.':'Se muestran los vasos disponibles; las ramas pequeñas se describen en la ficha.'):'El modelo no incluye '+(mode==='nerve'?'el plexo o las ramas nerviosas locales':mode==='lymph'?'la vía linfática descrita':'las ramas vasculares locales')+'. La ficha describe la relación; se mantiene el órgano como referencia.');
  if(targets.length){showRelationTargets(targets);showSurfaceControls();}openPanel('learn');revealRelation();
 }catch(e){if(epoch===filterVersion&&selected===owner){clearRelation();restoreOrganContext(context);relationStatus('No se pudo cargar esta vista. Toca el apartado para reintentar.')}console.error(e)}finally{button?.removeAttribute('aria-busy')}
}

function systemGroup(id){return ['muscular','skeletal','joints','integumentary'].includes(id)?'movement':['nervous','sensory','endocrine'].includes(id)?'control':['cardiac','arterial','venous','lymphatic'].includes(id)?'transport':'organs'}
function buildSystemGroups(){const list=$('#system-list');for(const [id,title,sub] of [['movement','Soporte y movimiento','Huesos, músculos y superficie'],['control','Control y sentidos','Integración y percepción'],['transport','Circulación y defensa','Corazón, vasos y linfa'],['organs','Órganos y funciones','Respiración, digestión y excreción']]){const group=document.createElement('details');group.open=true;group.className='system-group';group.dataset.systemGroup=id;group.innerHTML='<summary><span>'+title+'<small>'+sub+'</small></span><span class="group-count"></span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 10 5 5 5-5"/></svg></summary><div class="system-group-items"></div>';list.append(group)}}
function showSenseTools(){
 if(!selected||selected.data.system!=='sensory')return;
 const owner=selected,box=document.createElement('section');box.className='sense-tools';
 box.innerHTML='<h3>Estructuras</h3><p>Selecciona una estructura para verla sin las capas que la cubren.</p><div class="sense-pieces"></div><button class="sense-whole">Ver conjunto completo</button><p class="sense-limits">'+html(owner.data.limits)+'</p>';
 const pieces=selectedParts();for(const key of [...new Set(pieces.map(p=>p.key))]){const group=pieces.filter(p=>p.key===key),b=document.createElement('button');b.textContent=displayName(group[0].name);b.setAttribute('aria-pressed','false');b.onclick=()=>{stopLesson();clearRelation();studyKeys.clear();group.forEach(p=>{studyKeys.add(p.key);hidden.delete(p.key)});studyMode=true;isolation=false;rebuild();focusParts(group);box.querySelectorAll('.sense-pieces button').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));if(innerWidth<=760)closePanel()};box.querySelector('.sense-pieces').append(b)}
 box.querySelector('.sense-whole').onclick=()=>{stopLesson();clearRelation();studyKeys.clear();owner.keys.forEach(k=>studyKeys.add(k));studyMode=true;isolation=false;rebuild();focusSelection();box.querySelectorAll('.sense-pieces button').forEach(b=>b.setAttribute('aria-pressed','false'))};
 $('#info').append(box);
}
document.querySelectorAll('[data-sense]').forEach(b=>b.onclick=()=>selectCatalog(b.dataset.sense));

document.querySelectorAll('[data-drawer-panel]').forEach(b=>b.onclick=()=>openPanel(b.dataset.drawerPanel));
